<?php declare(strict_types=1);require_once dirname(__DIR__).'/includes/functions.php';requireLogin();$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT id,full_name,username,occupation,bio,profile_photo,created_at FROM users WHERE id=? AND role='member' AND is_active=1 AND is_banned=0");$s->execute([$id]);$m=$s->fetch();if(!$m){http_response_code(404);exit('Member not found.');}$s=db()->prepare("SELECT e.title_en,e.event_date,e.location,c.details FROM participation_claims c JOIN events e ON e.id=c.event_id WHERE c.member_id=? AND c.status='verified' ORDER BY c.participation_date DESC");$s->execute([$id]);$history=$s->fetchAll();$pageTitle=$m['full_name'];require dirname(__DIR__).'/includes/header.php';?><section class="section"><div class="container"><div class="member-public"><div><?php if($m['profile_photo']):?><img class="member-photo" src="<?=e($m['profile_photo'])?>" alt="<?=e($m['full_name'])?>"><?php else:?><div class="member-photo member-initials"><?=e(strtoupper(substr($m['full_name'],0,1)))?></div><?php endif;?></div><div><p class="eyebrow">ATACJL Member</p><h1 class="section-title"><?=e($m['full_name'])?></h1><?php if($m['occupation']):?><p><b><?=e($m['occupation'])?></b></p><?php endif;?><p class="copy"><?=nl2br(e($m['bio']??''))?></p><p class="muted">Member since <?=e(substr($m['created_at'],0,10))?></p></div></div><div class="form-shell" style="max-width:none;margin-top:35px"><h2>Verified involvement history</h2><?php if(!$history):?><p>No verified activity has been published yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Event</th><th>Date</th><th>Location</th><th>Details</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=e($h['title_en'])?></td><td><?=e($h['event_date'])?></td><td><?=e($h['location'])?></td><td><?=e($h['details'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></section><?php require dirname(__DIR__).'/includes/footer.php';
